#[no_mangle]
pub unsafe extern "C" fn tsvc_s2251_carried_scalar_expansion(p:*const f64,l:usize,q:*mut f64,c:usize)->i64{if p.is_null()||l<6||l>321{return -1}let x=unsafe{std::slice::from_raw_parts(p,l)};let r=x[0];if !r.is_finite()||r.fract()!=0.0||r<1.0||r>64.0{return -1}let n=r as usize;if l!=1+5*n||x[1..].iter().any(|v|!v.is_finite()||v.fract()!=0.0||v.abs()>1.0){return -1}if q.is_null()||c<2*n{return -2}let(mut a,mut b)=([0.0;64],[0.0;64]);let mut s=0.0;for i in 0..n{a[i]=s*x[1+4*n+i];s=x[1+n+i]+x[1+2*n+i];b[i]=a[i]+x[1+3*n+i]}let y=unsafe{std::slice::from_raw_parts_mut(q,2*n)};y[..n].copy_from_slice(&a[..n]);y[n..].copy_from_slice(&b[..n]);(2*n)as i64}
